ids = await orders_list_order_ids()
futs = [orders_get_order(order_id=i) for i in ids]
rows = [await f for f in futs]
t = {}
bad = []
for r in rows:
    a = r.get("amount"); g = r.get("region")
    if not isinstance(a,(int,float)) or not g: bad.append({k:v for k,v in r.items() if k!="detail"})
    else: t[g] = t.get(g,0)+a
